import {survivalBags,survivalPackItems,survivalBagStats,survivalPackFit,survivalPackView,packWeightLabel} from './survival-pack.js';
const packEsc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const packArtTiles={campus:0,messenger:1,hiking:2,duffel:3,food:4,water:5,canned:6,energybar:7,bandage:8,firstaid:9,parts:10,tape:11,repairkit:12,bottle:13};
function packArt(id){const tile=packArtTiles[id]??14;return `<span class="pack-item-icon pack-art" data-art="${id}" style="--item-x:${tile%4*100/3}%;--item-y:${Math.floor(tile/4)*100/3}%" aria-hidden="true"></span>`;}

function packUseReason(r,id){return ['bandage','firstaid'].includes(id)?(!r.members.some(m=>m.injury>0)?'치료할 부상자 없음':r.actions<1?'여력 부족':null):['repairkit','tape'].includes(id)?(!r.base?'거점에서 사용':r.base.integrity>=100?'문 상태 양호':r.actions<1?'여력 부족':null):null;}

function packButton(label,action,value='',disabled=false){return `<button data-action="${action}" data-value="${value}" ${disabled?'disabled':''}>${label}</button>`;}
function packSummary(bag,items){const stats=survivalBagStats(bag,items);return `<header class="pack-summary"><div>${packArt(bag)}<span>원정 가방</span><h2>${stats.name}</h2><p>칸과 최대 적재 무게를 모두 지켜야 해요.</p></div><div class="pack-meters"><label>수납 칸 <b>${stats.usedSlots} / ${stats.slots}</b><meter min="0" max="${stats.slots}" value="${stats.usedSlots}"></meter></label><label>물품 무게 <b>${packWeightLabel(stats.weight)} / ${packWeightLabel(stats.maxWeight)}</b><meter min="0" max="${stats.maxWeight}" value="${stats.weight}"></meter></label></div>${stats.over?'<p class="pack-warning">기존 짐이 한도를 넘어요. 삭제되지는 않지만 정리해야 새 물건을 담거나 출발할 수 있어요.</p>':''}</header>`;}
function packLootPanel(container,combat=false){
 const pool=container.pending;if(!pool)return '';const take=combat?'combatPackTake':'survivalPackLoot',equip=combat?'combatPackBag':'survivalPackBag';
 return `<section class="pack-found" aria-label="발견한 물자"><span>발견 · 아직 소지품이 아니에요</span><h3>${packEsc(pool.source)}</h3><p>필요한 것부터 골라 담으세요. 용량과 무게는 별도로 계산해요.</p><div class="pack-loot-grid">${pool.bags.map(id=>{const bag=survivalBags[id],blocked=survivalBagStats(id,container.items).over;return `<article class="pack-loot-card bag-find" data-found-bag="${id}">${packArt(id)}<div><small>가방 발견</small><h4>${bag.name}</h4><p>${bag.slots}칸 · 최대 ${packWeightLabel(bag.maxWeight)}</p><small>${bag.description}</small></div>${packButton(blocked?'현재 짐이 들어가지 않음':'이 가방으로 교체',equip,id,blocked||id===container.bag)}<small>현재 가방은 이곳에 남겨요.</small></article>`;}).join('')}${Object.entries(pool.items).filter(([,q])=>q>0).map(([id,q])=>{const item=survivalPackItems[id],blocked=survivalPackFit(container.bag,container.items,id);return `<article class="pack-loot-card" data-found-item="${id}">${packArt(id)}<div><small>${item.category}</small><h4>${item.name} <b>×${q}</b></h4><p>${packWeightLabel(item.weight)} / 개 · ${item.stack}개 묶음당 ${item.slots}칸</p><small>${item.use}</small></div>${packButton(blocked??'1개 챙기기',take,id,!!blocked)}</article>`;}).join('')||(!pool.bags.length?'<p>챙길 물건은 모두 확인했어요.</p>':'')}</div>${packButton(combat?'남은 물자 포기 · 상자 정리':'남은 물자 두고 수색 마치기',combat?'combatPackLeave':'survivalPackLeave')}<p class="pack-note">가방에 담은 것만 가져가요. 정리를 끝내면 남은 물자는 되찾지 못해요.</p></section>`;
}
export function survivalPackPage(state,storageOnly=false){
 const r=state.survivalRun,p=survivalPackView(state);if(!p)return '';
 if(!p.initialized)return `<article class="pack-empty"><h2>원정 가방 준비</h2><p>기존 물자는 그대로 보관돼요. 가방을 준비한 뒤 필요한 물건을 옮겨 담을 수 있어요.</p>${packButton('가방 준비 · 소비 없음','survivalPackInit')}</article>`;
 const available=Object.entries(survivalPackItems).filter(([id])=>(['food','water','bandage','parts'].includes(id)?r.resources[id]:p.stock[id])>0);
 const contents=`<section class="pack-contents"><div class="pack-section-heading"><h3>가방 안 물건</h3><span>같은 물품은 정해진 수량까지 한 묶음으로 담아요.</span></div><div class="pack-item-grid">${Object.entries(p.items).filter(([,q])=>q>0).map(([id,q])=>{const item=survivalPackItems[id],usable=!['parts','bottle'].includes(id),storeBlocked=!!p.pending,useReason=packUseReason(r,id);return `<article class="pack-item-card" data-packed-item="${id}">${packArt(id)}<h4>${item.name} ×${q}</h4><p>${packWeightLabel(item.weight*q)} · ${Math.ceil(q/item.stack)*item.slots}칸</p><small>${item.use}</small><div>${usable?packButton(useReason??'사용','survivalPackUse',id,!!useReason):''}${packButton('1개 보관','survivalPackStore',id,storeBlocked)}${packButton('1개 버리기','survivalPackDrop',id)}</div></article>`;}).join('')||'<p class="pack-note">가방이 비어 있어요. 보관함에서 출발할 물품을 챙기세요.</p>'}</div><p class="pack-note">사용하거나 버리면 실제 수량이 줄어요. 버린 물건은 되찾을 수 없어요. 음식·물은 태이에게, 치료 물품은 부상자 한 명에게 사용해요.</p></section>`;
 const stock=`<section class="pack-stock"><div class="pack-section-heading"><h3>${r.base?'거점 공동 보관함':'동료와 숨겨둔 공동 물자'}</h3><span>원정에는 가방에 담은 물품만 가져가요.</span></div><div class="pack-stock-tools">${packButton('기본 보급품 챙기기','survivalPackPrepare','',!!p.pending)}${packButton('가방 물건 모두 보관','survivalPackStoreAll','',!!p.pending)}</div><p class="pack-note">기본 준비: 보유한 범위에서 생수 2·붕대 1·에너지바 1. 보관함 자체는 현재 수량 제한이 없어요. 수색 중에는 보관함으로 바로 옮길 수 없어요.</p><div class="pack-stock-grid">${available.map(([id,item])=>{const q=['food','water','bandage','parts'].includes(id)?r.resources[id]:p.stock[id],blocked=p.pending?'수색을 마친 뒤 이용':survivalPackFit(p.bag,p.items,id);return `<article><span>${item.icon} ${item.name} <b>×${q}</b></span><div>${packButton(blocked??'1개 담기','survivalPackTake',id,!!blocked)}${!['parts','bottle'].includes(id)?packButton(packUseReason(r,id)??'여기서 사용','survivalStoredUse',id,!!p.pending||!!packUseReason(r,id)):''}</div></article>`;}).join('')||'<p>보관 중인 물건이 없어요.</p>'}</div></section>`;
 return `<section class="pack-page ${storageOnly?'storage-page':''}">${packSummary(p.bag,p.items)}${packLootPanel(p)}${storageOnly?stock+contents:contents+stock}</section>`;
}
export function combatPackPanel(b){
 if(!b?.survivalPack)return '';const meta=b.survivalPack,container={...meta,items:b.stash.items};return `<details class="combat-pack-panel" ${meta.pending?'open':''}><summary>원정 가방 · ${survivalBagStats(meta.bag,b.stash.items).usedSlots}/${survivalBags[meta.bag].slots}칸 · ${packWeightLabel(survivalBagStats(meta.bag,b.stash.items).weight)}</summary>${packSummary(meta.bag,b.stash.items)}${packLootPanel(container,true)}<div class="combat-pack-items">${Object.entries(b.stash.items).filter(([id,q])=>q>0&&survivalPackItems[id]).map(([id,q])=>`<p><span>${survivalPackItems[id].name} ×${q}</span>${packButton('1개 버리기','combatPackDrop',id)}</p>`).join('')}</div><p class="pack-note">가방에 챙긴 물건은 중단 후에도 가져와요. 성공 보너스는 승리 후 따로 골라 담아요. 활성 전투에서 상자 물자를 더 챙기려면 상자 옆으로 돌아가세요.</p></details>`;
}
